// Pair two opponents and punish the healthier fraction, rather than the larger HP pool.
const BALANCE_VERDICT_SIGNATURE=['天秤の裁定',25,7,'照準付近の敵と、その220以内の別の敵を結ぶ。3秒後、残りHP割合が高い方へ100%＋HP割合の差×300%の一撃（最大400%）。同率なら最初の敵。どちらかが倒れる・2体が350以上離れる・自分から500を超える・壁に遮られると解除。2体必要。再発動で置き換える。','M26 6V44M9 16L43 12M12 16L5 32H19ZM40 13L33 29H47ZM16 45H36'];
SIGNATURE_SKILLS.push(BALANCE_VERDICT_SIGNATURE);Object.assign(GEM.crafted_3_2,{name:BALANCE_VERDICT_SIGNATURE[0],cost:25,cool:7,desc:BALANCE_VERDICT_SIGNATURE[3],ability:null,signature:90,tags:['spell']});
SIGNATURE_AUDIO.push(['balanceverdict',310,.4]);SKILL_AUDIO_FAMILIES.heavy.add('balanceverdict');
function balanceLifeRatio(e){return clamp(e.hp/e.max,0,1);}
function balancePairValid(s){return s.pair?.length===2&&s.pair.every(e=>e.hp>0&&Number.isFinite(e.hp)&&Number.isFinite(e.max)&&e.max>0&&enemies.includes(e)&&dist(p,e)<=500&&lineClear(p,e))&&dist(...s.pair)<350&&lineClear(...s.pair);}
function balanceDecision(s){let [a,b]=s.pair,first=balanceLifeRatio(a),second=balanceLifeRatio(b);return{target:first>=second?a:b,mult:1+3*Math.abs(first-second)};}
const balanceVerdictCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{let result=balanceVerdictCastBase(build,...args);if(GEM[build.type]?.signature!==90)return result;let s=signatureSpells.at(-1);if(s?.mode!==90)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==90||v===s);s.owner=p;let a=s.target,b=a&&enemies.filter(e=>e!==a&&e.hp>0&&Number.isFinite(e.hp)&&Number.isFinite(e.max)&&e.max>0&&dist(a,e)<=220&&dist(p,e)<=500&&lineClear(p,e)&&lineClear(a,e)).sort((x,y)=>dist(a,x)-dist(a,y))[0];s.pair=b?[a,b]:[];if(!balancePairValid(s)){signatureSpells=signatureSpells.filter(v=>v!==s);say('近くの敵2体を結べません');}return result;};
const balanceVerdictStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==90)return balanceVerdictStepBase(s,dt);if(dead||p.hp<=0||s.owner!==p)return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;if(!balancePairValid(s))return false;s.time=Math.round((s.time+dt)*1e6)/1e6;if(s.time<3)return true;let verdict=balanceDecision(s);spellHit(verdict.target,s.damage*verdict.mult,s.build);burst(verdict.target.x,verdict.target.y,65,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(90,true,verdict.target.x,verdict.target.y);return false;};
const balanceVerdictPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{balanceVerdictPaintBase();for(let s of signatureSpells){if(s.mode!==90||s.owner!==p||!s.pair?.length||s.pair.some(e=>e.hp<=0))continue;let [a,b]=s.pair,color=ELEMENTS[s.build.elements[0]].color,verdict=balanceDecision(s);for(let e of s.pair)if(visibleAt(e.x,e.y)){groundRing(e.x,e.y,24,e===verdict.target?'#f5d48c':color,e===verdict.target?3:1);groundRing(e.x,e.y,30*Math.max(0,1-s.time/3),'#d6b7fa',1);}if(visibleAt(a.x,a.y)&&visibleAt(b.x,b.y)){paintLinkLine(a,b,'#d6b7fa',2);let q=project((a.x+b.x)/2,(a.y+b.y)/2),tilt=(balanceLifeRatio(a)-balanceLifeRatio(b))*10;ctx.save();ctx.strokeStyle='#f5d48c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x,q.y-78);ctx.lineTo(q.x,q.y-48);ctx.moveTo(q.x-17,q.y-68+tilt);ctx.lineTo(q.x+17,q.y-68-tilt);for(let side of [-1,1]){let x=q.x+side*17,y=q.y-68-side*tilt;ctx.moveTo(x,y);ctx.lineTo(x-6,y+13);ctx.lineTo(x+6,y+13);ctx.closePath();}ctx.stroke();ctx.restore();}}};
const balanceVerdictStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===90?{label:'裁定 '+Math.max(0,3-s.time).toFixed(1)+'秒 · '+Math.round(balanceDecision(s).mult*100)+'%',value:Math.max(0,1-s.time/3),waiting:true}:balanceVerdictStatusBase(s);
